    "id": "legacy-godfather",
    "sourceName": "Godfather Cocktail",
    "url": "https://www.diffordsguide.com/cocktails/recipe/864/godfather-cocktail",
    "image": "https://cdn.diffordsguide.com/cocktail/GRoezr/square/0/512x512.webp?v=1737701574",
