    "id": "legacy-harvey-wallbanger",
    "sourceName": "Harvey Wallbanger",
    "url": "https://www.diffordsguide.com/cocktails/recipe/936/harvey-wallbanger",
    "image": "https://cdn.diffordsguide.com/cocktail/gApQvr/square/1/512x512.webp?v=1766065488",
    "key": "diffords",
    "label": "Difford's",
